#include "nf_prediction.h"
#include <math.h>
#include <string.h>

static float state_error(const NfActorNetState *a,const NfActorNetState *b){float x=a->position.x-b->position.x,y=a->position.y-b->position.y,z=a->position.z-b->position.z;return sqrtf(x*x+y*y+z*z);}
void nf_prediction_init(NfPrediction *p){if(p==NULL)return;memset(p,0,sizeof(*p));p->next_sequence=1u;}
NfInputCommand nf_prediction_make_command(NfPrediction *p,uint64_t tick,NfMoveInput move){NfInputCommand c={0};if(p==NULL)return c;c.sequence=p->next_sequence++;c.client_tick=tick;c.move=move;return c;}
void nf_prediction_record(NfPrediction *p,const NfInputCommand *c,const NfActor *a){if(p==NULL||c==NULL||a==NULL)return;NfPredictionSlot *s=&p->history[c->sequence%NF_NET_HISTORY];s->valid=true;s->command=*c;nf_actor_to_net_state(a,&s->predicted);}
uint8_t nf_prediction_build_redundant_bundle(const NfPrediction *p,uint32_t newest,NfInputBundle *bundle){if(p==NULL||bundle==NULL||newest==0)return 0;bundle->count=0;uint32_t first=newest>=NF_NET_INPUT_REDUNDANCY-1u?newest-(NF_NET_INPUT_REDUNDANCY-1u):1u;for(uint32_t seq=first;seq<=newest;++seq){const NfPredictionSlot *s=&p->history[seq%NF_NET_HISTORY];if(s->valid&&s->command.sequence==seq)bundle->commands[bundle->count++]=s->command;}return bundle->count;}
bool nf_prediction_reconcile(NfPrediction *p,NfWorld *world,NfEntityId id,const NfActorNetState *auth,uint32_t ack,uint64_t server_tick,float threshold){if(p==NULL||world==NULL||auth==NULL)return false;NfActor *actor=nf_world_find_actor(world,id);if(actor==NULL)return false;NfPredictionSlot *ack_slot=&p->history[ack%NF_NET_HISTORY];float error=0.0f;bool have=ack_slot->valid&&ack_slot->command.sequence==ack;if(have)error=state_error(&ack_slot->predicted,auth);p->last_error=error;if(error>p->max_error)p->max_error=error;p->last_acknowledged=ack;bool mismatch=!have||error>threshold||(have&&ack_slot->predicted.mode!=auth->mode)||(have&&ack_slot->predicted.attached_collider!=auth->attached_collider);if(!mismatch)return false;
    uint32_t newest=p->next_sequence>0?p->next_sequence-1u:0u;nf_actor_apply_net_state(actor,auth,&world->movement);world->tick=server_tick;nf_world_sync_dynamic_geometry(world);for(uint32_t seq=ack+1u;seq<=newest;++seq){NfPredictionSlot *slot=&p->history[seq%NF_NET_HISTORY];if(!slot->valid||slot->command.sequence!=seq)continue;nf_world_set_input(world,id,slot->command.move);nf_world_step(world,1.0f/(float)NF_TICK_RATE);nf_actor_to_net_state(actor,&slot->predicted);}++p->corrections;return true;}
